/**
 * Contract tests cho `buildStandardAdminWhere`.
 *
 * Mục tiêu: đảm bảo filter contract mà `api-client.buildAdminListQuery()`
 * gửi (dạng `filter[column]=value`) được `parseListQuery` map vào `filters`
 * object, sau đó service truyền cho `buildStandardAdminWhere` sẽ dựng đúng
 * WHERE clause cho MikroORM.
 */
import { loadFixture } from '../data-test/fixture';
import { createFakeEntityManager } from '../data-test/fake-em';
import {
  buildStandardAdminWhere,
  type AdminColumnFiltersConfig,
} from './apply-column-filters';

describe('buildStandardAdminWhere — admin list filter contract', () => {
  describe('soft-delete status', () => {
    it('status="active" → deletedAt: null', () => {
      const where = buildStandardAdminWhere(
        {},
        {},
        'active',
        { softDeleteField: 'deletedAt' },
      );
      expect(where.deletedAt).toBeNull();
    });

    it('status="deleted" → deletedAt: { $ne: null }', () => {
      const where = buildStandardAdminWhere(
        {},
        {},
        'deleted',
        { softDeleteField: 'deletedAt' },
      );
      expect(where.deletedAt).toEqual({ $ne: null });
    });

    it('status="all" → bỏ soft-delete filter', () => {
      const where = buildStandardAdminWhere(
        {},
        {},
        'all',
        { softDeleteField: 'deletedAt' },
      );
      expect(where.deletedAt).toBeUndefined();
    });

    it('softDeleteField mặc định là deletedAt', () => {
      const where = buildStandardAdminWhere({}, {}, 'active');
      expect(where.deletedAt).toBeNull();
    });
  });

  describe('text type', () => {
    it('builds { $like: %term% }', () => {
      const config: AdminColumnFiltersConfig = {
        title: { type: 'text', path: 'title' },
      };
      const where = buildStandardAdminWhere(
        { title: 'hello' },
        config,
        'active',
      );
      expect(where.title).toEqual({ $like: '%hello%' });
    });
  });

  describe('exact type', () => {
    it('set exact value', () => {
      const config: AdminColumnFiltersConfig = {
        status: { type: 'exact', path: 'status' },
      };
      const where = buildStandardAdminWhere(
        { status: 'active' },
        config,
        'all',
      );
      expect(where.status).toBe('active');
    });
  });

  describe('number type', () => {
    it('parses numeric string sang number', () => {
      const config: AdminColumnFiltersConfig = {
        count: { type: 'number', path: 'count' },
      };
      const where = buildStandardAdminWhere(
        { count: '42' },
        config,
        'all',
      );
      expect(where.count).toBe(42);
    });

    it('NaN → bỏ filter (không set)', () => {
      const config: AdminColumnFiltersConfig = {
        count: { type: 'number', path: 'count' },
      };
      const where = buildStandardAdminWhere(
        { count: 'abc' },
        config,
        'all',
      );
      expect(where.count).toBeUndefined();
    });
  });

  describe('boolean type', () => {
    it('"true" → true', () => {
      const config: AdminColumnFiltersConfig = {
        active: { type: 'boolean', path: 'isActive' },
      };
      const where = buildStandardAdminWhere(
        { active: 'true' },
        config,
        'all',
      );
      expect(where.isActive).toBe(true);
    });

    it('"false" → false', () => {
      const config: AdminColumnFiltersConfig = {
        active: { type: 'boolean', path: 'isActive' },
      };
      const where = buildStandardAdminWhere(
        { active: 'false' },
        config,
        'all',
      );
      expect(where.isActive).toBe(false);
    });

    it('other value (vd "1") → bỏ filter (chỉ chấp nhận "true"/"false")', () => {
      const config: AdminColumnFiltersConfig = {
        active: { type: 'boolean', path: 'isActive' },
      };
      const where = buildStandardAdminWhere(
        { active: '1' },
        config,
        'all',
      );
      expect(where.isActive).toBeUndefined();
    });
  });

  describe('entityId type', () => {
    it('numeric string → number', () => {
      const config: AdminColumnFiltersConfig = {
        author: { type: 'entityId', path: 'authorId' },
      };
      const where = buildStandardAdminWhere(
        { author: '5' },
        config,
        'all',
      );
      expect(where.authorId).toBe(5);
    });

    it('non-numeric (CUID) → bỏ filter', () => {
      const config: AdminColumnFiltersConfig = {
        author: { type: 'entityId', path: 'authorId' },
      };
      const where = buildStandardAdminWhere(
        { author: 'cm123abc' },
        config,
        'all',
      );
      expect(where.authorId).toBeUndefined();
    });
  });

  describe('dateRange type', () => {
    it('1 date → $gte', () => {
      const config: AdminColumnFiltersConfig = {
        date: { type: 'dateRange', path: 'createdAt' },
      };
      const where = buildStandardAdminWhere(
        { date: '2025-01-01' },
        config,
        'all',
      );
      expect(where.createdAt).toEqual({ $gte: new Date('2025-01-01') });
    });

    it('2 dates comma-separated → $gte + $lte', () => {
      const config: AdminColumnFiltersConfig = {
        date: { type: 'dateRange', path: 'createdAt' },
      };
      const where = buildStandardAdminWhere(
        { date: '2025-01-01,2025-12-31' },
        config,
        'all',
      );
      expect(where.createdAt).toEqual({
        $gte: new Date('2025-01-01'),
        $lte: new Date('2025-12-31'),
      });
    });
  });

  describe('unknown filter column → bỏ qua (không throw)', () => {
    it('filter không có trong config → bỏ', () => {
      const config: AdminColumnFiltersConfig = {
        title: { type: 'text', path: 'title' },
      };
      const where = buildStandardAdminWhere(
        { unknownColumn: 'x', title: 'hello' },
        config,
        'all',
      );
      expect((where as Record<string, unknown>).unknownColumn).toBeUndefined();
      expect(where.title).toEqual({ $like: '%hello%' });
    });
  });

  describe('empty filter value → bỏ qua', () => {
    it('filter value rỗng hoặc null → bỏ', () => {
      const config: AdminColumnFiltersConfig = {
        title: { type: 'text', path: 'title' },
      };
      const where = buildStandardAdminWhere(
        { title: '', author: null as unknown as string },
        config,
        'all',
      );
      expect(where.title).toBeUndefined();
    });
  });

  describe('multiple filters cùng lúc', () => {
    it('build nhiều field trong where', () => {
      const config: AdminColumnFiltersConfig = {
        title: { type: 'text', path: 'title' },
        published: { type: 'boolean', path: 'published' },
        author: { type: 'entityId', path: 'authorId' },
      };
      const where = buildStandardAdminWhere(
        { title: 'hello', published: 'true', author: '7' },
        config,
        'active',
      );
      expect(where.title).toEqual({ $like: '%hello%' });
      expect(where.published).toBe(true);
      expect(where.authorId).toBe(7);
      expect(where.deletedAt).toBeNull();
    });
  });

  describe('integration với fixture data', () => {
    it('em.find tìm đúng record khi áp filter từ buildStandardAdminWhere', async () => {
      const fixture = loadFixture();
      const em = createFakeEntityManager(fixture);
      em.__reset();
      const postId = (fixture.posts[0] as { id?: number | string }).id;
      if (!postId) return;
      const where = buildStandardAdminWhere(
        { id: String(postId) },
        { id: { type: 'entityId', path: 'id' } },
        'all',
      );
      const found = await em.find('Post', where as never);
      expect(found.length).toBeGreaterThan(0);
      expect(found.some((p: Record<string, unknown>) => p.id === postId)).toBe(true);
    });

    it('em.find với status="active" chỉ trả về bản ghi chưa soft-delete', async () => {
      const fixture = loadFixture();
      const em = createFakeEntityManager(fixture);
      em.__reset();
      const where = buildStandardAdminWhere(
        {},
        {},
        'active',
        { softDeleteField: 'deletedAt' },
      );
      const found = await em.find('Post', where as never);
      // tất cả bản ghi trả về phải có deletedAt == null
      for (const row of found) {
        expect((row as Record<string, unknown>).deletedAt).toBeNull();
      }
    });
  });
});

src/common/apply-column-filters.ts.content:
/**
 * Apply Column Filters.
 *
 * Bám sát pattern `apps/main/api/src/common/apply-column-filters.ts`.
 *
 * Helper dựng WHERE clause cho filter dạng cột (text / exact / number /
 * numberRange / dateRange / boolean / entityId). Dùng cho admin list API.
 */
import type { FilterQuery } from '@mikro-orm/core';

export type AdminColumnFilterType =
  | 'text'
  | 'exact'
  | 'number'
  | 'numberRange'
  | 'dateRange'
  | 'boolean'
  | 'entityId';

export interface AdminColumnFilterField {
  type: AdminColumnFilterType;
  /** Đường dẫn field entity — hỗ trợ nested quan hệ, vd. `['linkedEvent', 'title']`. */
  path: string | string[];
}

export type AdminColumnFiltersConfig = Record<string, AdminColumnFilterField>;

function toPathSegments(path: string | string[]): string[] {
  return Array.isArray(path) ? path : [path];
}

function setNestedWhere(
  where: Record<string, unknown>,
  path: string[],
  value: unknown,
): void {
  if (path.length === 0) return;

  let current = where;
  for (let i = 0; i < path.length - 1; i += 1) {
    const key = path[i];
    const next = current[key];
    if (!next || typeof next !== 'object' || Array.isArray(next)) {
      current[key] = {};
    }
    current = current[key] as Record<string, unknown>;
  }

  const lastKey = path[path.length - 1];
  const existing = current[lastKey];
  if (
    existing &&
    typeof existing === 'object' &&
    !Array.isArray(existing) &&
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    current[lastKey] = { ...existing, ...value };
    return;
  }
  current[lastKey] = value;
}

function applyDateRange(
  where: Record<string, unknown>,
  path: string[],
  raw: string,
): void {
  const dates = raw
    .split(',')
    .map((x) => x.trim())
    .filter(Boolean);
  if (dates.length === 0) return;

  if (dates.length === 1) {
    setNestedWhere(where, path, { $gte: new Date(dates[0]) });
    return;
  }

  setNestedWhere(where, path, {
    $gte: new Date(dates[0]),
    $lte: new Date(dates[1]),
  });
}

function applyFieldFilter(
  where: Record<string, unknown>,
  field: AdminColumnFilterField,
  raw: string,
): void {
  const path = toPathSegments(field.path);

  switch (field.type) {
    case 'text': {
      const term = `%${raw}%`;
      setNestedWhere(where, path, { $like: term });
      return;
    }
    case 'exact': {
      setNestedWhere(where, path, raw);
      return;
    }
    case 'number': {
      const n = Number(raw);
      if (!Number.isNaN(n)) {
        setNestedWhere(where, path, n);
      }
      return;
    }
    case 'numberRange': {
      const parts = raw
        .split(',')
        .map((x) => x.trim())
        .filter(Boolean)
        .map(Number);
      if (parts.length === 1 && !Number.isNaN(parts[0])) {
        setNestedWhere(where, path, { $gte: parts[0] });
        return;
      }
      if (parts.length >= 2) {
        const [from, to] = parts;
        const range: Record<string, number> = {};
        if (!Number.isNaN(from)) range.$gte = from;
        if (!Number.isNaN(to)) range.$lte = to;
        setNestedWhere(where, path, range);
      }
      return;
    }
    case 'dateRange': {
      applyDateRange(where, path, raw);
      return;
    }
    case 'boolean': {
      if (raw === 'true' || raw === 'false') {
        setNestedWhere(where, path, raw === 'true');
      }
      return;
    }
    case 'entityId': {
      const n = Number(raw);
      if (!Number.isNaN(n) && n > 0) {
        setNestedWhere(where, path, n);
      }
      return;
    }
    default:
      return;
  }
}

/** Áp `filter[columnId]` lên MikroORM `where` theo config từng cột. */
export function applyColumnFilters(
  where: Record<string, unknown>,
  filters: Record<string, string> | undefined,
  config: AdminColumnFiltersConfig,
): void {
  if (!filters) return;

  for (const [key, value] of Object.entries(filters)) {
    if (!value?.trim()) continue;
    const field = config[key];
    if (!field) continue;
    applyFieldFilter(where, field, value);
  }
}

export type StandardAdminListParams = {
  search?: string;
  status?: 'active' | 'deleted' | 'all';
  statusFilter?: number;
  updatedAtFrom?: string;
  updatedAtTo?: string;
  deletedAtFrom?: string;
  deletedAtTo?: string;
  filters?: Record<string, string>;
  searchFields?: string[];
  filterConfig?: AdminColumnFiltersConfig;
};

function applySoftDeleteStatus(
  where: Record<string, unknown>,
  status: StandardAdminListParams['status'],
): void {
  const s = status ?? 'active';
  if (s === 'deleted') where.deletedAt = { $ne: null };
  else if (s === 'active') where.deletedAt = null;
}

function applyLegacyRangeFilters(
  where: Record<string, unknown>,
  params: StandardAdminListParams,
): void {
  if (params.statusFilter != null) where.status = params.statusFilter;

  if (params.updatedAtFrom) {
    where.updatedAt = {
      ...(where.updatedAt as object),
      $gte: new Date(params.updatedAtFrom),
    };
  }
  if (params.updatedAtTo) {
    where.updatedAt = {
      ...(where.updatedAt as object),
      $lte: new Date(params.updatedAtTo),
    };
  }
  if (params.deletedAtFrom) {
    where.deletedAt = {
      ...(where.deletedAt as object),
      $gte: new Date(params.deletedAtFrom),
    };
  }
  if (params.deletedAtTo) {
    where.deletedAt = {
      ...(where.deletedAt as object),
      $lte: new Date(params.deletedAtTo),
    };
  }
}

/** Ghép soft-delete, search, legacy date/status và `filter[column]`. */
export function buildStandardAdminListWhere(
  params: StandardAdminListParams,
): Record<string, unknown> {
  const where: Record<string, unknown> = {};

  applySoftDeleteStatus(where, params.status);
  applyLegacyRangeFilters(where, params);

  if (params.search?.trim() && params.searchFields?.length) {
    const q = params.search.trim();
    where.$or = params.searchFields.map((field) => ({
      [field]: { $like: `%${q}%` },
    }));
  }

  if (params.filterConfig) {
    applyColumnFilters(where, params.filters, params.filterConfig);
  }

  return where;
}

/**
 * Build a FilterQuery từ admin column filters + soft-delete status.
 */
export function buildStandardAdminWhere<T extends object>(
  filters: Record<string, string> | undefined,
  config: AdminColumnFiltersConfig,
  status: 'active' | 'deleted' | 'all' = 'active',
  options: { softDeleteField?: string } = {},
): FilterQuery<T> {
  const where: Record<string, unknown> = {};
  const softDeleteField = options.softDeleteField ?? 'deletedAt';

  // Soft-delete status filter
  if (status === 'active') {
    where[softDeleteField] = null;
  } else if (status === 'deleted') {
    where[softDeleteField] = { $ne: null };
  }
  // 'all' -> không thêm soft-delete filter

  if (!filters) return where as FilterQuery<T>;

  for (const [key, raw] of Object.entries(filters)) {
    if (raw == null || raw === '') continue;
    const field = config[key];
    if (!field) continue;
    applyFieldFilter(where, field, raw);
  }

  return where as FilterQuery<T>;
}

