/**
 * BaseEventSpeakersController — HTTP admin event speakers (@workspace/api-server).
 */
import {
  ApiTags,
  ApiOperation,
  ApiHeader,
  ApiBody,
  ApiResponse,
} from '@nestjs/swagger';
import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  Headers,
  Res,
} from '@nestjs/common';
import type { Response } from 'express';
import { BaseAdminHttpController } from '../../bases/base-admin-http.controller';
import { Permissions, parseAdminListLimit, isBulkAction } from '../../common';
import { ADMIN_ROUTES, PERMISSIONS } from '../../config';
import type { BaseEventSpeakersService } from './event-speakers.service';

export type IEventSpeakersControllerService = Pick<
  BaseEventSpeakersService,
  | 'list'
  | 'getById'
  | 'create'
  | 'update'
  | 'delete'
  | 'bulk'
>;
/** @deprecated Dùng `IEventSpeakersControllerService`. */
export type IEventSpeakersAdminControllerService = IEventSpeakersControllerService;

@ApiTags('Event Speakers')
@Permissions(PERMISSIONS.EVENT_SPEAKERS_VIEW)
@Controller(ADMIN_ROUTES.EVENT_SPEAKERS)
export class BaseEventSpeakersController extends BaseAdminHttpController {
  constructor(
    protected readonly service: IEventSpeakersControllerService,
  ) {
    super();
  }

  @Get()
  @ApiOperation({ summary: 'List event speakers by eventId with pagination' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async list(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('eventId') eventId?: string,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;
    if (!eventId?.trim()) {
      return this.sendError(res, 'eventId là bắt buộc', 400);
    }

    const result = await this.service.list({
      eventId: eventId.trim(),
      page: Math.max(1, parseInt(String(page), 10) || 1),
      limit: parseAdminListLimit(limit, 10),
    });
    return this.sendSuccess(res, {
      data: result.data,
      pagination: result.pagination,
    });
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get event speaker by ID' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async getById(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;

    const row = await this.service.getById(id);
    if (!row) return this.sendNotFound(res, 'Không tìm thấy event speaker');
    return this.sendSuccess(res, row);
  }

  @Post()
  @Permissions(PERMISSIONS.EVENT_SPEAKERS_CREATE)
  @ApiOperation({ summary: 'Create new event speaker' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async create(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body()
    body: {
      eventId: string;
      speakerId: number;
      sortOrder?: number;
      role?: string;
      presentationTitle?: string;
      startTime?: string;
      endTime?: string;
      duration?: number;
    },
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;
    if (!body?.eventId?.trim()) {
      return this.sendError(res, 'eventId là bắt buộc', 400);
    }
    if (!body?.speakerId) {
      return this.sendError(res, 'speakerId là bắt buộc', 400);
    }

    const created = await this.service.create({
      eventId: body.eventId.trim(),
      speakerId: body.speakerId,
      sortOrder: body.sortOrder,
      role: body.role?.trim() ?? null,
      presentationTitle: body.presentationTitle?.trim() ?? null,
      startTime: body.startTime ?? null,
      endTime: body.endTime ?? null,
      duration: body.duration ?? null,
    });
    return this.sendSuccess(res, created, { status: 201 });
  }

  @Put(':id')
  @Permissions(PERMISSIONS.EVENT_SPEAKERS_UPDATE)
  @ApiOperation({ summary: 'Update event speaker by ID' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async update(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
    @Body()
    body: {
      speakerId?: number;
      sortOrder?: number;
      role?: string;
      presentationTitle?: string;
      startTime?: string;
      endTime?: string;
      duration?: number;
    },
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;

    const updated = await this.service.update(id, {
      speakerId: body?.speakerId,
      sortOrder: body?.sortOrder,
      role: body?.role !== undefined ? (body.role?.trim() ?? null) : undefined,
      presentationTitle:
        body?.presentationTitle !== undefined
          ? (body.presentationTitle?.trim() ?? null)
          : undefined,
      startTime:
        body?.startTime !== undefined ? (body.startTime ?? null) : undefined,
      endTime: body?.endTime !== undefined ? (body.endTime ?? null) : undefined,
      duration: body?.duration,
    });
    if (!updated) return this.sendNotFound(res, 'Không tìm thấy event speaker');
    return this.sendSuccess(res, updated);
  }

  @Delete(':id')
  @Permissions(PERMISSIONS.EVENT_SPEAKERS_DELETE)
  @ApiOperation({ summary: 'Delete event speaker' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async delete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    return this.handleBoolMutation(
      res,
      headers,
      () => this.service.delete(id),
      'Đã xóa event speaker',
      'Không tìm thấy event speaker',
    );
  }

  @Post('bulk')
  @Permissions(PERMISSIONS.EVENT_SPEAKERS_MANAGE)
  @ApiOperation({ summary: 'Bulk action on event speakers' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  @ApiBody({ description: 'Bulk action with ids' })
  @ApiResponse({ status: 200, description: 'Bulk action completed' })
  async bulk(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body() body: { action?: string; ids?: string[] },
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;

    const action = body?.action;
    const ids = Array.isArray(body?.ids) ? body.ids : [];
    if (!action || !isBulkAction(action)) {
      return this.sendError(res, 'Action không hợp lệ', 400);
    }

    const result = await this.service.bulk(action, ids);
    return this.sendSuccess(
      res,
      { affected: result.affected, message: result.message },
      { message: result.message },
    );
  }
}

/**
 * EventSpeakers Module — NestJS wiring cho admin event-speakers.
 */
import { Module, type ModuleMetadata } from '@nestjs/common';
import { BaseEventSpeakersController } from './event-speakers.controller';

@Module({})
export class BaseEventSpeakersModule {
  static forRoot(metadata: ModuleMetadata = {}): ModuleMetadata {
    return {
      imports: metadata.imports ?? [],
      controllers: [...(metadata.controllers ?? []), BaseEventSpeakersController],
      providers: metadata.providers ?? [],
      exports: metadata.exports ?? [],
    };
  }
}

export { BaseEventSpeakersController } from './event-speakers.controller';
export {
  BaseEventSpeakersService,
  type EventSpeakerRowDto,
  type ListEventSpeakersParams,
  type ListEventSpeakersResult,
} from './event-speakers.service';

/**
 * Event speakers admin service — logic dùng chung; app binding entity.
 */
import { Injectable } from '@nestjs/common';
import { EntityManager } from '@mikro-orm/core';
import {
  applyBulkAction,
  type BulkAction,
  type BulkResult,
} from '../../common/bulk-actions';
import {
  normalizePageLimit,
  paginationMeta,
  ADMIN_TABLE_EXPORT_MAX_LIMIT,
} from '../../common/pagination';
import { safeIsoString } from '../../common/date-utils';
import { toEntityId } from '../../common/entity-id';

export interface EventSpeakerRowDto {
  id: number;
  eventId: number;
  speakerId: number;
  speakerName: string;
  speakerTitle: string | null;
  speakerOrganization: string | null;
  speakerAvatar: string | null;
  sortOrder: number;
  role: string | null;
  presentationTitle: string | null;
  startTime: string | null;
  endTime: string | null;
  duration: number | null;
  attachments: unknown;
}

export interface ListEventSpeakersParams {
  eventId: string | number;
  page: number;
  limit: number;
}

export interface ListEventSpeakersResult {
  data: EventSpeakerRowDto[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

type EventSpeakerWithRelations = {
  id: number;
  sortOrder: number;
  role?: string | null;
  presentationTitle?: string | null;
  startTime?: Date | string | null;
  endTime?: Date | string | null;
  duration?: number | null;
  attachments?: unknown;
  event: { id: number };
  speaker: {
    id: number;
    name: string;
    title?: string | null;
    organization?: string | null;
    avatar?: string | null;
  };
};

function mapRow(r: EventSpeakerWithRelations): EventSpeakerRowDto {
  return {
    id: r.id,
    eventId: r.event.id,
    speakerId: r.speaker.id,
    speakerName: r.speaker.name,
    speakerTitle: r.speaker.title ?? null,
    speakerOrganization: r.speaker.organization ?? null,
    speakerAvatar: r.speaker.avatar ?? null,
    sortOrder: r.sortOrder,
    role: r.role ?? null,
    presentationTitle: r.presentationTitle ?? null,
    startTime: safeIsoString(r.startTime),
    endTime: safeIsoString(r.endTime),
    duration: r.duration ?? null,
    attachments: r.attachments ?? null,
  };
}

@Injectable()
export abstract class BaseEventSpeakersService {
  protected abstract getEm(): EntityManager;
  protected abstract getEventSpeakerEntity(): new () => Record<string, unknown>;
  protected abstract getEventEntity(): new () => Record<string, unknown>;
  protected abstract getSpeakerEntity(): new () => Record<string, unknown>;

  async list(
    params: ListEventSpeakersParams,
  ): Promise<ListEventSpeakersResult> {
    const EventSpeaker = this.getEventSpeakerEntity();
    const { page, limit, skip } = normalizePageLimit(
      params.page,
      params.limit,
      ADMIN_TABLE_EXPORT_MAX_LIMIT,
    );
    const [rows, total] = await Promise.all([
      this.getEm().find(
        EventSpeaker,
        { event: toEntityId(params.eventId) },
        {
          populate: ['speaker', 'event'],
          orderBy: { sortOrder: 'ASC' },
          offset: skip,
          limit,
        },
      ),
      this.getEm().count(EventSpeaker, { event: toEntityId(params.eventId) }),
    ]);
    return {
      data: (rows as EventSpeakerWithRelations[]).map(mapRow),
      pagination: paginationMeta(page, limit, total),
    };
  }

  async getById(id: string): Promise<EventSpeakerRowDto | null> {
    const EventSpeaker = this.getEventSpeakerEntity();
    const r = await this.getEm().findOne(
      EventSpeaker,
      { id: toEntityId(id) },
      { populate: ['speaker', 'event'] },
    );
    if (!r) return null;
    return mapRow(r as EventSpeakerWithRelations);
  }

  async create(data: {
    eventId: string;
    speakerId: number;
    sortOrder?: number;
    role?: string | null;
    presentationTitle?: string | null;
    startTime?: Date | string | null;
    endTime?: Date | string | null;
    duration?: number | null;
  }): Promise<EventSpeakerRowDto> {
    const EventSpeaker = this.getEventSpeakerEntity();
    const created = new EventSpeaker() as EventSpeakerWithRelations;
    created.event = this.getEm().getReference(
      this.getEventEntity(),
      toEntityId(data.eventId),
    ) as { id: number };
    created.speaker = this.getEm().getReference(
      this.getSpeakerEntity(),
      toEntityId(data.speakerId),
    ) as EventSpeakerWithRelations['speaker'];
    if (data.sortOrder !== undefined) created.sortOrder = data.sortOrder;
    if (data.role !== undefined) created.role = data.role;
    if (data.presentationTitle !== undefined) {
      created.presentationTitle = data.presentationTitle;
    }
    if (data.startTime !== undefined) {
      created.startTime =
        typeof data.startTime === 'string'
          ? new Date(data.startTime)
          : data.startTime;
    }
    if (data.endTime !== undefined) {
      created.endTime =
        typeof data.endTime === 'string'
          ? new Date(data.endTime)
          : data.endTime;
    }
    if (data.duration !== undefined) created.duration = data.duration;
    await this.getEm().persistAndFlush(created);
    await this.getEm().populate(created, ['speaker', 'event']);
    return mapRow(created);
  }

  async update(
    id: string,
    data: {
      speakerId?: number;
      sortOrder?: number;
      role?: string | null;
      presentationTitle?: string | null;
      startTime?: Date | string | null;
      endTime?: Date | string | null;
      duration?: number | null;
    },
  ): Promise<EventSpeakerRowDto | null> {
    const EventSpeaker = this.getEventSpeakerEntity();
    const existing = (await this.getEm().findOne(
      EventSpeaker,
      { id: toEntityId(id) },
      { populate: ['speaker', 'event'] },
    )) as EventSpeakerWithRelations | null;
    if (!existing) return null;
    if (data.speakerId !== undefined) {
      existing.speaker = this.getEm().getReference(
        this.getSpeakerEntity(),
        toEntityId(data.speakerId),
      ) as EventSpeakerWithRelations['speaker'];
    }
    if (data.sortOrder !== undefined) existing.sortOrder = data.sortOrder;
    if (data.role !== undefined) existing.role = data.role;
    if (data.presentationTitle !== undefined) {
      existing.presentationTitle = data.presentationTitle;
    }
    if (data.startTime !== undefined) {
      existing.startTime =
        typeof data.startTime === 'string'
          ? new Date(data.startTime)
          : data.startTime;
    }
    if (data.endTime !== undefined) {
      existing.endTime =
        typeof data.endTime === 'string'
          ? new Date(data.endTime)
          : data.endTime;
    }
    if (data.duration !== undefined) existing.duration = data.duration;
    await this.getEm().persistAndFlush(existing);
    return mapRow(existing);
  }

  async delete(id: string): Promise<boolean> {
    const EventSpeaker = this.getEventSpeakerEntity();
    const r = await this.getEm().findOne(EventSpeaker, { id: toEntityId(id) });
    if (!r) return false;
    await this.getEm().removeAndFlush(r);
    return true;
  }

  async bulk(action: BulkAction, ids: string[]): Promise<BulkResult> {
    const EventSpeaker = this.getEventSpeakerEntity();
    return applyBulkAction(this.getEm(), EventSpeaker, action, ids, {
      label: 'gan dien gia',
    });
  }
}

