    search?: string;
    status?: string;
    filters?: Record<string, string>;
  }): Promise<{
    data: ParentStudentsRowDto[];
    pagination: { page: number; limit: number; total: number; totalPages: number };
  }>;
  review(
    id: string | number,
    action: 'approved' | 'rejected',
    reviewerId: string,
  ): Promise<ParentStudentsRowDto | null>;
  listByParent(parentId: string | number): Promise<ParentStudentsRowDto[]>;
  addStudentRequest(data: AddParentStudentInput): Promise<ParentStudentsRowDto>;
  removeForParent(id: string | number, parentId: string | number): Promise<boolean>;
}

@ApiTags('ParentStudents')
export class BaseParentStudentsController {
  private readonly parentStudentsService: IParentStudentsControllerService;

  constructor(service: IParentStudentsControllerService) {
    this.parentStudentsService = service;
  }

  @Get()
  @ApiOperation({ summary: 'List parent-student requests' })
  @ApiResponse({ status: 200, description: 'Parent-student requests retrieved successfully' })
  async list(
    @Query() query: Record<string, string | string[] | undefined>,
  ): Promise<
    ApiResponsePayload<{
      data: ParentStudentsRowDto[];
      pagination: { page: number; limit: number; total: number; totalPages: number };
    }>
  > {
    const filters: Record<string, string> = {};
    for (const [key, value] of Object.entries(query)) {
      if (key.startsWith('filter[') && key.endsWith(']') && value) {
        const column = key.slice(7, -1);
        const raw = Array.isArray(value) ? value[0] : value;
        if (raw?.trim()) filters[column] = raw.trim();
      }
    }
    if (typeof query.status === 'string' && query.status.trim()) {
      filters.status = query.status.trim();
    }
    if (typeof query.createdAt === 'string' && query.createdAt.trim()) {
      filters.createdAt = query.createdAt.trim();
    }

    const result = await this.parentStudentsService.list({
      page: parseAdminListPage(query.page),
      limit: parseAdminListLimit(query.limit, 20),
      search: typeof query.search === 'string' ? query.search.trim() : '',
      status: 'all',
      filters,
    });
    return createSuccessResponse(result).body;
  }

  @Patch(':id/review')
  @ApiOperation({ summary: 'Review parent-student request' })
  @ApiResponse({ status: 200, description: 'Parent-student request reviewed successfully' })
  async review(
    @Param('id') id: string,
    @Body() body: { action: 'approved' | 'rejected'; note?: string },
    @Headers() headers: Record<string, string | undefined>,
  ): Promise<ApiResponsePayload<ParentStudentsRowDto | null>> {
    if (!['approved', 'rejected'].includes(body.action)) {
      throw new BadRequestException(
        createErrorResponse('action phải là approved hoặc rejected', {
          status: 400,
        }).body,
      );
    }
    const reviewerId =
      headers['x-user-id']?.trim() ||
      headers['X-User-Id']?.trim() ||
      'system';
    const result = await this.parentStudentsService.review(id, body.action, reviewerId);
    if (!result) {
      throw new NotFoundException(
        createErrorResponse('Không tìm thấy', { status: 404 }).body,
      );
    }
    return createSuccessResponse(result).body;
  }
}

@Controller()
@ApiTags('ParentMyStudents')
export class BaseParentMyStudentsController {
  private readonly logger = new Logger(BaseParentMyStudentsController.name);

  constructor(private readonly service: IParentStudentsControllerService) {}

  private getUserId(headers: Record<string, string | undefined>): string {
    const userId =
      headers['x-user-id']?.trim() ||
      headers['X-User-Id']?.trim() ||
      headers['x-userid']?.trim();
    if (!userId) {
      throw new UnauthorizedException(
        createErrorResponse('Chưa đăng nhập', { status: 401 }).body,
      );
    }
    return userId;
  }

  private async ensureApprovedStudent(
    parentId: string,
    studentCode: string,
  ): Promise<void> {
    const links = await this.service.listByParent(parentId);
    const approved = links.find(
      (item) => item.studentCode === studentCode && item.status === 'approved',
    );
    if (!approved) {
      throw new ForbiddenException(
        createErrorResponse(
          'Học sinh chưa được duyệt hoặc không thuộc tài khoản này',
          { status: 403 },
        ).body,
      );
    }
  }

  private async fetchExternalData<T>(
    path: string,
    fallbackData: T,
    noConfigMessage: string,
    errorMessage: string,
  ): Promise<ApiResponsePayload<T>> {
    const externalApiUrl = process.env.EXTERNAL_API_URL;
    if (!externalApiUrl) {
      return createSuccessResponse(fallbackData, { message: noConfigMessage }).body;
    }

    const fetchHeaders: Record<string, string> = {
      'Content-Type': 'application/json',
    };
    if (process.env.EXTERNAL_API_TOKEN) {
      fetchHeaders.Authorization = `Bearer ${process.env.EXTERNAL_API_TOKEN}`;
    }

    try {
      const response = await fetch(`${externalApiUrl}${path}`, {
        headers: fetchHeaders,
        signal: AbortSignal.timeout(10000),
      });
      if (!response.ok) {
        throw new Error(`API điểm trả về lỗi: ${response.status}`);
      }
      const data = (await response.json()) as T;
      return createSuccessResponse(data).body;
    } catch (error) {
      this.logger.error(errorMessage, error);
      const message =
        error instanceof Error && error.message.startsWith('API điểm trả về lỗi:')
          ? error.message
          : errorMessage;
      throw new BadRequestException(
        createErrorResponse(message, { status: 400 }).body,
      );
    }
  }

  @Get('parent/my-students')
  @ApiOperation({ summary: 'List my students for current parent' })
  async list(
    @Headers() headers: Record<string, string | undefined>,
  ): Promise<ApiResponsePayload<ParentStudentsRowDto[]>> {
    const parentId = this.getUserId(headers);
    const data = await this.service.listByParent(parentId);
    return createSuccessResponse(data).body;
  }

  @Post('parent/my-students')
  @ApiOperation({ summary: 'Add student link request for current parent' })
  async add(
    @Headers() headers: Record<string, string | undefined>,
    @Body() body: { studentCode: string; studentName?: string; note?: string },
  ): Promise<ApiResponsePayload<ParentStudentsRowDto>> {
    const parentId = this.getUserId(headers);
    if (!body.studentCode?.trim()) {
      throw new BadRequestException(
        createErrorResponse('Mã sinh viên không được để trống', {
          status: 400,
        }).body,
      );
    }
    const data = await this.service.addStudentRequest({
      parentId: Number.parseInt(parentId, 10),
      studentCode: body.studentCode,
      studentName: body.studentName,
      note: body.note,
    });
    return createSuccessResponse(data).body;
  }

  @Delete('parent/my-students/:id')
  @ApiOperation({ summary: 'Delete current parent student link request' })
  async remove(
    @Param('id') id: string,
    @Headers() headers: Record<string, string | undefined>,
  ): Promise<ApiResponsePayload<{ id: string }>> {
    const parentId = this.getUserId(headers);
    const ok = await this.service.removeForParent(id, parentId);
    if (!ok) {
      throw new NotFoundException(
        createErrorResponse('Không tìm thấy hoặc không có quyền', {
          status: 404,
        }).body,
      );
    }
    return createSuccessResponse({ id }).body;
  }

  @Get('parent/my-students/scores/detailed/:studentCode')
  @ApiOperation({ summary: 'Get detailed scores for an approved student' })
  async getDetailedScores(
    @Param('studentCode') studentCode: string,
    @Headers() headers: Record<string, string | undefined>,
  ): Promise<ApiResponsePayload<unknown[]>> {
    const parentId = this.getUserId(headers);
    await this.ensureApprovedStudent(parentId, studentCode);
    return this.fetchExternalData(
      `/api/scores/detailed/${encodeURIComponent(studentCode)}`,
      [],
      'EXTERNAL_API_URL chưa được cấu hình',
      'Không thể lấy dữ liệu điểm chi tiết',
    );
  }

  @Get('parent/my-students/averages/year/:studentCode')
  @ApiOperation({ summary: 'Get year averages for an approved student' })
  async getYearAverages(
    @Param('studentCode') studentCode: string,
    @Headers() headers: Record<string, string | undefined>,
  ): Promise<ApiResponsePayload<unknown[]>> {
    const parentId = this.getUserId(headers);
    await this.ensureApprovedStudent(parentId, studentCode);
    return this.fetchExternalData(
      `/api/averages/year/${encodeURIComponent(studentCode)}`,
      [],
      'EXTERNAL_API_URL chưa được cấu hình',
      'Không thể lấy dữ liệu điểm trung bình năm',
    );
  }

  @Get('parent/my-students/averages/terms/:studentCode')
  @ApiOperation({ summary: 'Get term averages for an approved student' })
  async getTermAverages(
    @Param('studentCode') studentCode: string,
    @Headers() headers: Record<string, string | undefined>,
  ): Promise<ApiResponsePayload<unknown[]>> {
    const parentId = this.getUserId(headers);
    await this.ensureApprovedStudent(parentId, studentCode);
    return this.fetchExternalData(
      `/api/averages/terms/${encodeURIComponent(studentCode)}`,
      [],
      'EXTERNAL_API_URL chưa được cấu hình',
      'Không thể lấy dữ liệu điểm trung bình học kỳ',
    );
  }

  @Get('parent/my-students/averages/overall/:studentCode')
  @ApiOperation({ summary: 'Get overall average for an approved student' })
  async getOverallAverage(
    @Param('studentCode') studentCode: string,
    @Headers() headers: Record<string, string | undefined>,
  ): Promise<ApiResponsePayload<unknown>> {
    const parentId = this.getUserId(headers);
    await this.ensureApprovedStudent(parentId, studentCode);
    return this.fetchExternalData(
      `/api/averages/overall/${encodeURIComponent(studentCode)}`,
      null,
      'EXTERNAL_API_URL chưa được cấu hình',
      'Không thể lấy dữ liệu tổng hợp điểm',
    );
  }
}

/**
 * ParentStudents Module.
 */
import { Module, type ModuleMetadata } from '@nestjs/common';
import {
  BaseParentMyStudentsController,
  BaseParentStudentsController,
} from './parent-student.controller';

@Module({})
export class BaseParentStudentsModule {
  static forRoot(metadata: ModuleMetadata = {}): ModuleMetadata {
    return {
      imports: metadata.imports ?? [],
      controllers: [
        ...(metadata.controllers ?? []),
        BaseParentStudentsController,
        BaseParentMyStudentsController,
      ],
      providers: metadata.providers ?? [],
      exports: metadata.exports ?? [],
    };
  }
}

export {
  BaseParentStudentsController,
  BaseParentMyStudentsController,
} from './parent-student.controller';
export {
  BaseParentStudentsService,
  type ParentStudentsRowDto,
  type AddParentStudentInput,
  type ListParentStudentsResult,
} from './parent-student.service';

/**
 * ParentStudents Service — domain logic (materialize → apps/main/api module-bases).
 */
import { Injectable, Logger } from '@nestjs/common';
import type { EntityManager, FilterQuery } from '@mikro-orm/core';
import { applyColumnFilters } from '../../common/apply-column-filters';
import {
  ADMIN_TABLE_EXPORT_MAX_LIMIT,
  normalizePageLimit,
  paginationMeta,
  relationEntityId,
  safeIsoString,
  safeIsoStringNow,
  toEntityId,
} from '../../common';
import { PARENT_STUDENT_COLUMN_FILTERS } from './parent-student-column-filters';

export interface ParentStudentsRowDto {
  id: number;
  parentId: number;
  parentEmail: string | null;
  parentName: string | null;
  parentPhone: string | null;
  studentCode: string;
  studentName: string | null;
  note: string | null;
  status: string;
  reviewedBy: string | null;
  reviewedAt: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface ListParentStudentsResult {
  data: ParentStudentsRowDto[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

export interface AddParentStudentInput {
  parentId: number;
  studentCode: string;
  studentName?: string;
  note?: string;
}

export interface ParentStudentsRealtimePort {
  pendingApproval(payload: {
    resource: string;
    id: number;
    status: string;
    title: string;
    description?: string | null;
    actionUrl?: string | null;
    actorUserId?: string;
  }): void;
  parentStudentReviewed(payload: {
    id: number;
    parentId: number;
    studentCode: string;
    studentName: string | null;
    status: 'approved' | 'rejected';
    reviewedAt: string;
    reviewedBy: string;
  }): void;
}

function mapRow(r: Record<string, unknown>): ParentStudentsRowDto {
  const parent = r.parent;
  const parentObj =
    parent != null && typeof parent === 'object'
      ? (parent as Record<string, unknown>)
      : null;
  return {
    id: r.id as number,
    parentId: relationEntityId(r.parent) ?? relationEntityId(parentObj) ?? 0,
    parentEmail:
      typeof parentObj?.email === 'string' ? parentObj.email : null,
    parentName:
      parentObj?.name == null
        ? null
        : typeof parentObj.name === 'string'
          ? parentObj.name
          : null,
    parentPhone:
      typeof parentObj?.phone === 'string' ? parentObj.phone : null,
    studentCode: String(r.studentCode ?? ''),
    studentName: (r.studentName as string | null | undefined) ?? null,
    note: (r.note as string | null | undefined) ?? null,
    status: String(r.status ?? ''),
    reviewedBy: (r.reviewedBy as string | null | undefined) ?? null,
    reviewedAt: safeIsoString(r.reviewedAt as Date | string | null | undefined),
    createdAt: safeIsoStringNow(r.createdAt as Date | string | null | undefined),
    updatedAt: safeIsoStringNow(r.updatedAt as Date | string | null | undefined),
  };
}

@Injectable()
export abstract class BaseParentStudentsService {
  protected readonly logger = new Logger(BaseParentStudentsService.name);

  protected abstract getEm(): EntityManager;
  protected abstract getEntity(): new () => Record<string, unknown>;
  protected abstract getUserEntity(): new () => Record<string, unknown>;
  protected abstract getAdminRealtime(): ParentStudentsRealtimePort;

  async listByParent(parentId: string): Promise<ParentStudentsRowDto[]> {
    const em = this.getEm();
    const Entity = this.getEntity();
    const rows = await em.find(
      Entity,
      { parent: toEntityId(parentId) },
      {
        populate: ['parent'] as never,
        orderBy: { createdAt: 'DESC' },
      },
    );
    return rows.map((row) => mapRow(row as Record<string, unknown>));
  }

  async listPending(params: {
    page: number;
    limit: number;
  }): Promise<ListParentStudentsResult> {
    const em = this.getEm();
    const Entity = this.getEntity();
    const { page, limit, skip } = normalizePageLimit(
      params.page,
      params.limit,
      ADMIN_TABLE_EXPORT_MAX_LIMIT,
    );
    const where = { status: 'pending' } as FilterQuery<Record<string, unknown>>;
    const [rows, total] = await Promise.all([
      em.find(Entity, where, {
        populate: ['parent'] as never,
        orderBy: { createdAt: 'ASC' },
        offset: skip,
        limit,
      }),
      em.count(Entity, where),
    ]);
    return {
      data: rows.map((row) => mapRow(row as Record<string, unknown>)),
      pagination: paginationMeta(page, limit, total),
    };
  }

  async listAll(params: {
    page: number;
    limit: number;
    status?: string;
    search?: string;
    createdAt?: string;
    filters?: Record<string, string>;
  }): Promise<ListParentStudentsResult> {
    const em = this.getEm();
    const Entity = this.getEntity();
    const { page, limit, skip } = normalizePageLimit(
      params.page,
      params.limit,
      ADMIN_TABLE_EXPORT_MAX_LIMIT,
    );
    const where: Record<string, unknown> = {};
    if (
      params.status &&
      ['pending', 'approved', 'rejected'].includes(params.status)
    ) {
      where.status = params.status;
    }
    if (params.search?.trim()) {
      const q = params.search.trim();
      const escaped = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      where.$or = [
        { studentCode: { $re: `(?i)${escaped}` } },
        { studentName: { $re: `(?i)${escaped}` } },
        { parentId: { $re: `(?i)${escaped}` } },
      ];
    }
    if (params.createdAt?.trim()) {
      const [fromStr, toStr] = params.createdAt.split(',');
      const dateRange: Record<string, Date> = {};
      if (fromStr?.trim()) {
        const fromDate = new Date(fromStr.trim());
        if (!Number.isNaN(fromDate.getTime())) {
          dateRange.$gte = fromDate;
        }
      }
      if (toStr?.trim()) {
        const toDate = new Date(toStr.trim());
        toDate.setHours(23, 59, 59, 999);
        if (!Number.isNaN(toDate.getTime())) {
          dateRange.$lte = toDate;
        }
      }
      if (Object.keys(dateRange).length > 0) {
        where.createdAt = dateRange;
      }
    }
    applyColumnFilters(where, params.filters, PARENT_STUDENT_COLUMN_FILTERS);
    const whereQuery = where as FilterQuery<Record<string, unknown>>;
    const [rows, total] = await Promise.all([
      em.find(Entity, whereQuery, {
        populate: ['parent'] as never,
        orderBy: { createdAt: 'DESC' },
        offset: skip,
        limit,
      }),
      em.count(Entity, whereQuery),
    ]);
    return {
      data: rows.map((row) => mapRow(row as Record<string, unknown>)),
      pagination: paginationMeta(page, limit, total),
    };
  }

  /** Alias cho template controller pkg (list admin chuẩn). */
  async list(params: {
    page: number;
    limit: number;
    search?: string;
    status?: string;
    filters?: Record<string, string>;
  }): Promise<ListParentStudentsResult> {
    return this.listAll({
      page: params.page,
      limit: params.limit,
      search: params.search,
      status: params.filters?.status ?? params.status,
      createdAt: params.filters?.createdAt,
      filters: params.filters,
    });
  }

  async addStudentRequest(
    data: AddParentStudentInput,
  ): Promise<ParentStudentsRowDto> {
    const em = this.getEm();
    const Entity = this.getEntity();
    const User = this.getUserEntity();
    const existing = await em.findOne(Entity, {
      parent: toEntityId(String(data.parentId)),
      studentCode: data.studentCode.trim(),
    });
    if (existing) {
      throw new Error('Bạn đã gửi yêu cầu liên kết với mã sinh viên này rồi.');
    }

    const ps = new Entity() as Record<string, unknown>;
    ps.parent = em.getReference(User, data.parentId);
    ps.studentCode = data.studentCode.trim();
    ps.studentName = data.studentName?.trim() ?? null;
    ps.note = data.note?.trim() ?? null;
    ps.status = 'pending';
    await em.persistAndFlush(ps);
    const row = mapRow(ps);
    this.getAdminRealtime().pendingApproval({
      resource: 'parent-students',
      id: row.id,
      status: 'pending',
      title: 'Yêu cầu liên kết phụ huynh mới',
      description: `${row.studentCode}${row.studentName ? ` — ${row.studentName}` : ''}`,
      actionUrl: '/admin/parent-students',
      actorUserId: String(data.parentId),
    });
    return row;
  }

  async review(
    id: string,
    action: 'approved' | 'rejected',
    reviewedBy: string,
  ): Promise<ParentStudentsRowDto | null> {
    const em = this.getEm();
    const Entity = this.getEntity();
    const ps = await em.findOne(Entity, { id: toEntityId(id) });
    if (!ps) return null;
    const row = ps as Record<string, unknown>;
    row.status = action;
    row.reviewedBy = reviewedBy;
    row.reviewedAt = new Date();
    await em.persistAndFlush(ps);
    const mapped = mapRow(row);
    this.getAdminRealtime().parentStudentReviewed({
      id: mapped.id,
      parentId: mapped.parentId,
      studentCode: mapped.studentCode,
      studentName: mapped.studentName,
      status: action,
      reviewedAt: mapped.reviewedAt ?? new Date().toISOString(),
      reviewedBy,
    });
    return mapped;
  }

  async remove(id: string, parentId: string): Promise<boolean> {
    const em = this.getEm();
    const Entity = this.getEntity();
    const ps = await em.findOne(Entity, {
      id: toEntityId(id),
      parent: toEntityId(parentId),
    });
    if (!ps) return false;
    await em.removeAndFlush(ps);
    return true;
  }

  async removeForParent(
    id: string | number,
    parentId: string | number,
  ): Promise<boolean> {
    return this.remove(String(id), String(parentId));
  }

  async removeByAdmin(id: string): Promise<boolean> {
    const em = this.getEm();
    const Entity = this.getEntity();
    const ps = await em.findOne(Entity, { id: toEntityId(id) });
    if (!ps) return false;
    await em.removeAndFlush(ps);
    return true;
  }

  async getById(id: string): Promise<ParentStudentsRowDto | null> {
    const em = this.getEm();
    const Entity = this.getEntity();
    const ps = await em.findOne(
      Entity,
      { id: toEntityId(id) },
      { populate: ['parent'] as never },
    );
    return ps ? mapRow(ps as Record<string, unknown>) : null;
  }
}

