  ): Promise<Response> {
    this.logger.log(`getById id=${id}`);

    if (!userIdHeader?.trim()) {
      const { statusCode, body } = this.createErrorResponse(
        'Thiếu header X-User-Id',
        { statusCode: 401 },
      );
      return res.status(statusCode).json(body);
    }

    if (!id) {
      const { statusCode, body } = this.createErrorResponse(
        'Thiếu ID người dùng',
        { statusCode: 400 },
      );
      return res.status(statusCode).json(body);
    }

    const row = await this.service.getById(id);

    if (!row) {
      const { statusCode, body } = this.createErrorResponse(
